SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- 1. Bổ sung cột sku và price cho bảng product_variant (nếu chưa có)
SET @col_sku = (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'product_variant' AND column_name = 'sku');
SET @sql_sku = IF(@col_sku = 0, 'ALTER TABLE product_variant ADD COLUMN sku VARCHAR(100) NULL AFTER product_id', 'SELECT 1');
PREPARE stmt_sku FROM @sql_sku; EXECUTE stmt_sku; DEALLOCATE PREPARE stmt_sku;

SET @col_price = (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'product_variant' AND column_name = 'price');
SET @sql_price = IF(@col_price = 0, 'ALTER TABLE product_variant ADD COLUMN price DECIMAL(19,2) NULL AFTER storage', 'SELECT 1');
PREPARE stmt_price FROM @sql_price; EXECUTE stmt_price; DEALLOCATE PREPARE stmt_price;

SET @idx_sku = (SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema = DATABASE() AND table_name = 'product_variant' AND index_name = 'uk_variant_sku');
SET @sql_idx = IF(@idx_sku = 0, 'ALTER TABLE product_variant ADD CONSTRAINT uk_variant_sku UNIQUE (sku)', 'SELECT 1');
PREPARE stmt_idx FROM @sql_idx; EXECUTE stmt_idx; DEALLOCATE PREPARE stmt_idx;

