INSERT INTO reviews (id, comment, created_at, images, rating, status, order_item_id, product_id, user_id, updated_at) VALUES (4, 'Acer TravelMate P4 TMP414-53 chạy khá mượt và ổn định trong tầm giá, đáp ứng tốt nhu cầu hằng ngày. Độ hoàn thiện cao cấp chuẩn doanh nhân, cầm lên tay cảm giác sang trọng và cực kỳ bền bỉ. Sẽ cho 4 sao rưỡi nếu trọng lượng nhẹ thêm chút nữa, tổng thể rất ổn.', '2026-11-08 17:37:00', NULL, 4, 'APPROVED', 3, 65, 3, '2026-11-08 17:37:00');
INSERT INTO reviews (id, comment, created_at, images, rating, status, order_item_id, product_id, user_id, updated_at) VALUES (5, 'Rất ưng Acer Aspire Vero 15 AV15-53P trong tầm giá này! Đóng gói của shop cẩn thận, giao hàng nhanh đúng hẹn. Rất phù hợp cho sinh viên học tập, làm đồ án và giải trí nhẹ nhàng sau giờ lên lớp. Chắc chắn sẽ giới thiệu LaptopStore cho bạn bè.', '2026-11-08 00:37:00', NULL, 5, 'APPROVED', 4, 67, 3, '2026-11-08 00:37:00');
