INSERT INTO reviews (id, comment, created_at, images, rating, status, order_item_id, product_id, user_id, updated_at) VALUES (106, 'Pin trên ASUS ROG Zephyrus G14 GA403UV OLED trụ khá tốt cho cả buổi làm việc di động ngoài quán cà phê mà không cần mang sạc. Sức mạnh của NVIDIA GeForce RTX 4060 8GB GDDR6 hỗ trợ xuất file và preview timeline 4K mượt mà đáng kinh ngạc. Đáng đồng tiền bát gạo, rất hài lòng.', '2026-10-10 15:22:00', NULL, 5, 'APPROVED', 105, 50, 23, '2026-10-10 15:22:00');
