INSERT INTO reviews (id, comment, created_at, images, rating, status, order_item_id, product_id, user_id, updated_at) VALUES (114, 'Máy bị nóng vùng kê tay bên trái khi render lâu, trải nghiệm chưa thật sự ưng ý. Mình mua phiên bản Ice Blue (16GB / 512GB) mong shop hỗ trợ kiểm tra kỹ hơn.', '2026-09-01 03:58:00', NULL, 1, 'APPROVED', 113, 21, 29, '2026-09-01 03:58:00');
