INSERT INTO reviews (id, comment, created_at, images, rating, status, order_item_id, product_id, user_id, updated_at) VALUES (142, 'Pin trên ASUS Vivobook 15 M1502YA trụ khá tốt cho cả buổi làm việc di động ngoài quán cà phê mà không cần mang sạc. Mang lên giảng đường hay thư viện cả ngày gọn nhẹ, pin ổn định. Trải nghiệm mua sắm tuyệt vời, ủng hộ shop lâu dài.', '2026-11-12 23:59:00', NULL, 5, 'APPROVED', 141, 12, 5, '2026-11-12 23:59:00');
INSERT INTO reviews (id, comment, created_at, images, rating, status, order_item_id, product_id, user_id, updated_at) VALUES (143, 'Các cổng kết nối đầy đủ trên HP OMEN Transcend 14 OLED giúp mình cắm màn hình ngoài và USB tiện lợi không cần hub rời. Sức mạnh của NVIDIA GeForce RTX 4060 8GB GDDR6 hỗ trợ xuất file và preview timeline 4K mượt mà đáng kinh ngạc. Trải nghiệm mua sắm tuyệt vời, ủng hộ shop lâu dài.', '2026-11-13 07:52:00', NULL, 5, 'APPROVED', 142, 81, 6, '2026-11-13 07:52:00');
