INSERT INTO reviews (id, comment, created_at, images, rating, status, order_item_id, product_id, user_id, updated_at) VALUES (146, 'Loa trên MSI Vector 16 HX A14VHG nghe trong và rõ, gọi họp Zoom hay xem phim giải trí đều rất ổn. Hệ thống tản nhiệt kép đẩy gió ra sau hiệu quả, kê tay không bị nóng rát. Nếu ai đang tìm laptop tầm giá này thì nên chốt ngay em này.', '2026-11-18 03:00:00', NULL, 5, 'APPROVED', 145, 96, 8, '2026-11-18 03:00:00');
INSERT INTO reviews (id, comment, created_at, images, rating, status, order_item_id, product_id, user_id, updated_at) VALUES (147, 'Camera sắc nét, mở khóa nhanh và bản lề Dell Inspiron 14 5430 gập mở chắc tay không bị rung lắc. Bản lề chắc chắn, gõ văn bản nhiều giờ liên tục rất êm tay không ồn. Nếu ai đang tìm laptop tầm giá này thì nên chốt ngay em này.', '2026-11-17 19:00:00', NULL, 5, 'APPROVED', 146, 1, 8, '2026-11-17 19:00:00');
