INSERT INTO reviews (id, comment, created_at, images, rating, status, order_item_id, product_id, user_id, updated_at) VALUES (173, 'Shop tư vấn rất nhiệt tình cấu hình Gigabyte U4 UD-50S1823SO Ultrabook, nhận hàng kiểm tra nguyên seal chính hãng. Làm Excel file nặng, Word, PowerPoint và họp trực tuyến cả ngày máy vẫn phản hồi tức thì. Trải nghiệm mua sắm tuyệt vời, ủng hộ shop lâu dài.', '2026-10-09 14:12:00', NULL, 5, 'APPROVED', 172, 117, 23, '2026-10-09 14:12:00');
INSERT INTO reviews (id, comment, created_at, images, rating, status, order_item_id, product_id, user_id, updated_at) VALUES (174, 'Hiệu năng của Intel Core Ultra 9 185H trên MSI Stealth 16 AI Studio A1VGG xử lý đa nhiệm hàng chục tab Chrome và phần mềm cực kỳ nhẹ nhàng. Render video Premiere, chỉnh ảnh Lightroom và dựng 3D Blender nhanh hơn hẳn máy cũ của mình. Nếu ai đang tìm laptop tầm giá này thì nên chốt ngay em này.', '2026-10-16 01:16:00', NULL, 5, 'APPROVED', 173, 95, 24, '2026-10-16 01:16:00');
INSERT INTO reviews (id, comment, created_at, images, rating, status, order_item_id, product_id, user_id, updated_at) VALUES (175, 'Màn hình 14.5" 3.2K (3200x2000) hiển thị màu sắc tươi tắn, góc nhìn rộng làm việc lâu không mỏi mắt. Độ chuẩn màu màn hình cao giúp làm đồ họa và chỉnh sửa ảnh yên tâm về sai lệch màu. Nếu ai đang tìm laptop tầm giá này thì nên chốt ngay em này.', '2026-08-28 03:34:00', NULL, 5, 'APPROVED', 174, 71, 25, '2026-08-28 03:34:00');
