INSERT INTO reviews (id, comment, created_at, images, rating, status, order_item_id, product_id, user_id, updated_at) VALUES (177, 'Chất lượng hoàn thiện Lenovo ThinkBook 14 G6 IRL tốt, bàn phím gõ êm và touchpad rộng rãi. Trọng lượng gọn nhẹ dễ bỏ balo mang đi làm mỗi ngày mà không bị nặng vai. Rất đáng mua trong phân khúc giá hiện tại.', '2026-09-19 14:25:00', NULL, 4, 'APPROVED', 176, 44, 26, '2026-09-19 14:25:00');
