INSERT INTO reviews (id, comment, created_at, images, rating, status, order_item_id, product_id, user_id, updated_at) VALUES (206, 'Đã cân nhắc nhiều mẫu trước khi chốt HP OmniBook 5 AI 16-AF1048TU và thấy quyết định hoàn toàn xứng đáng. Bản lề chắc chắn, gõ văn bản nhiều giờ liên tục rất êm tay không ồn. Nếu ai đang tìm laptop tầm giá này thì nên chốt ngay em này.', '2026-11-18 02:00:00', NULL, 5, 'APPROVED', 205, 24, 6, '2026-11-18 02:00:00');
INSERT INTO reviews (id, comment, created_at, images, rating, status, order_item_id, product_id, user_id, updated_at) VALUES (207, 'Ngoại hình ASUS VivoBook 14 X1407CA-LY008W bên ngoài nhìn sang và sắc sảo hơn cả trong ảnh giới thiệu. Bản lề chắc chắn, gõ văn bản nhiều giờ liên tục rất êm tay không ồn. Nếu ai đang tìm laptop tầm giá này thì nên chốt ngay em này.', '2026-11-05 16:49:00', NULL, 5, 'APPROVED', 206, 25, 7, '2026-11-05 16:49:00');
