INSERT INTO reviews (id, comment, created_at, images, rating, status, order_item_id, product_id, user_id, updated_at) VALUES (242, 'Đã cân nhắc nhiều mẫu trước khi chốt ASUS ROG Strix G16 G614JU và thấy quyết định hoàn toàn xứng đáng. Hệ thống tản nhiệt kép đẩy gió ra sau hiệu quả, kê tay không bị nóng rát. Bảo hành chính hãng đầy đủ nên dùng cực kỳ yên tâm.', '2026-08-11 07:50:00', NULL, 5, 'APPROVED', 241, 49, 32, '2026-08-11 07:50:00');
