INSERT INTO reviews (id, comment, created_at, images, rating, status, order_item_id, product_id, user_id, updated_at) VALUES (304, 'Pin trên Dell Precision 3591 Workstation trụ khá tốt cho cả buổi làm việc di động ngoài quán cà phê mà không cần mang sạc. Render video Premiere, chỉnh ảnh Lightroom và dựng 3D Blender nhanh hơn hẳn máy cũ của mình. Chắc chắn sẽ giới thiệu LaptopStore cho bạn bè.', '2026-09-12 08:00:00', NULL, 5, 'APPROVED', 303, 75, 31, '2026-09-12 08:00:00');
INSERT INTO reviews (id, comment, created_at, images, rating, status, order_item_id, product_id, user_id, updated_at) VALUES (305, 'Các cổng kết nối đầy đủ trên Dell 14 DC14250 DC4C5375W1 giúp mình cắm màn hình ngoài và USB tiện lợi không cần hub rời. Làm Excel file nặng, Word, PowerPoint và họp trực tuyến cả ngày máy vẫn phản hồi tức thì. Chắc chắn sẽ giới thiệu LaptopStore cho bạn bè.', '2026-09-12 02:00:00', NULL, 5, 'APPROVED', 304, 21, 31, '2026-09-12 02:00:00');
INSERT INTO reviews (id, comment, created_at, images, rating, status, order_item_id, product_id, user_id, updated_at) VALUES (306, 'Giá sale đợt này cho HP Spectre x360 14 OLED 2024 quá hời so với hiệu năng mang lại, anh em sinh viên hay đi làm đều hợp. Độ hoàn thiện cao cấp chuẩn doanh nhân, cầm lên tay cảm giác sang trọng và cực kỳ bền bỉ. Chắc chắn sẽ giới thiệu LaptopStore cho bạn bè.', '2026-08-11 08:45:00', NULL, 5, 'APPROVED', 305, 83, 32, '2026-08-11 08:45:00');
INSERT INTO reviews (id, comment, created_at, images, rating, status, order_item_id, product_id, user_id, updated_at) VALUES (307, 'Mình dùng Apple MacBook Pro 14 M3 để code và chạy máy ảo Docker rất mượt, không bị nghẽn RAM. Độ chuẩn màu màn hình cao giúp làm đồ họa và chỉnh sửa ảnh yên tâm về sai lệch màu. Chắc chắn sẽ giới thiệu LaptopStore cho bạn bè.', '2026-08-07 03:45:00', NULL, 5, 'APPROVED', 306, 8, 32, '2026-08-07 03:45:00');
INSERT INTO reviews (id, comment, created_at, images, rating, status, order_item_id, product_id, user_id, updated_at) VALUES (308, 'HP Pavilion Aero 13-be2098AU hiệu năng ổn trong tầm giá nhưng thời lượng pin thực tế chỉ tầm 4 tiếng khi mở nhiều tab. Tuy vậy nhìn chung làm Excel file nặng, Word, PowerPoint và họp trực tuyến cả ngày máy vẫn phản hồi tức thì.', '2026-08-19 04:38:00', NULL, 3, 'APPROVED', 307, 91, 33, '2026-08-19 04:38:00');
INSERT INTO reviews (id, comment, created_at, images, rating, status, order_item_id, product_id, user_id, updated_at) VALUES (309, 'Máy HP ZBook Firefly 14 G10 chạy tốt các tác vụ cơ bản, tuy nhiên vỏ hơi dễ bám vân tay nên cần lau thường xuyên. Tuy vậy nhìn chung độ chuẩn màu màn hình cao giúp làm đồ họa và chỉnh sửa ảnh yên tâm về sai lệch màu.', '2026-08-21 14:38:00', NULL, 3, 'APPROVED', 308, 89, 33, '2026-08-21 14:38:00');
INSERT INTO reviews (id, comment, created_at, images, rating, status, order_item_id, product_id, user_id, updated_at) VALUES (310, 'Mình mới nhận Gigabyte AORUS Master 16 AI được hơn 1 tuần, cảm nhận ban đầu là máy hoàn thiện cực kỳ chắc chắn. Sức mạnh của NVIDIA GeForce RTX 4080 12GB GDDR6 hỗ trợ xuất file và preview timeline 4K mượt mà đáng kinh ngạc. Cho shop 5 sao vì dịch vụ giao hàng và hậu mãi chu đáo!', '2026-08-11 01:44:00', NULL, 5, 'APPROVED', 309, 119, 34, '2026-08-11 01:44:00');
INSERT INTO reviews (id, comment, created_at, images, rating, status, order_item_id, product_id, user_id, updated_at) VALUES (311, 'Rất ưng Dell XPS 14 9440 OLED trong tầm giá này! Đóng gói của shop cẩn thận, giao hàng nhanh đúng hẹn. Sức mạnh của NVIDIA GeForce RTX 4050 6GB GDDR6 hỗ trợ xuất file và preview timeline 4K mượt mà đáng kinh ngạc. Cho shop 5 sao vì dịch vụ giao hàng và hậu mãi chu đáo!', '2026-06-24 05:45:00', NULL, 5, 'APPROVED', 310, 71, 35, '2026-06-24 05:45:00');
INSERT INTO reviews (id, comment, created_at, images, rating, status, order_item_id, product_id, user_id, updated_at) VALUES (312, 'Sau 2 tuần sử dụng Acer Aspire Vero 15 AV15-53P cho công việc hằng ngày, thực sự hài lòng với độ mượt mà. Mang lên giảng đường hay thư viện cả ngày gọn nhẹ, pin ổn định. Cho shop 5 sao vì dịch vụ giao hàng và hậu mãi chu đáo!', '2026-06-22 21:45:00', NULL, 5, 'APPROVED', 311, 67, 35, '2026-06-22 21:45:00');
INSERT INTO reviews (id, comment, created_at, images, rating, status, order_item_id, product_id, user_id, updated_at) VALUES (313, 'Chất lượng hoàn thiện HP OMEN 16-wf0000 Gaming tốt, bàn phím gõ êm và touchpad rộng rãi. Card đồ họa NVIDIA GeForce RTX 4060 8GB GDDR6 phát huy sức mạnh rất tốt, nhiệt độ CPU/GPU giữ ở mức an toàn khi chơi lâu. Rất đáng mua trong phân khúc giá hiện tại.', '2026-06-25 10:02:00', NULL, 4, 'APPROVED', 312, 80, 36, '2026-06-25 10:02:00');
INSERT INTO reviews (id, comment, created_at, images, rating, status, order_item_id, product_id, user_id, updated_at) VALUES (314, 'Máy chạy đúng cấu hình mô tả, có điều dây sạc đi kèm hơi nặng khi mang đi học. Tuy vậy nhìn chung tần số quét màn hình cao giúp di chuột và combat game FPS cực đã mắt. [Đơn cấu hình Core Black 32GB / 1TB #310]', '2026-06-29 02:02:00', NULL, 3, 'APPROVED', 313, 94, 36, '2026-06-29 02:02:00');
INSERT INTO reviews (id, comment, created_at, images, rating, status, order_item_id, product_id, user_id, updated_at) VALUES (315, 'Ngoại hình Acer Aspire Lite 16 Gen 2 AL16-52P-76DU bên ngoài nhìn sang và sắc sảo hơn cả trong ảnh giới thiệu. Bản lề chắc chắn, gõ văn bản nhiều giờ liên tục rất êm tay không ồn. Đáng đồng tiền bát gạo, rất hài lòng.', '2026-06-16 05:48:00', NULL, 5, 'APPROVED', 314, 27, 37, '2026-06-16 05:48:00');
INSERT INTO reviews (id, comment, created_at, images, rating, status, order_item_id, product_id, user_id, updated_at) VALUES (316, 'Mua Acer Swift Edge 16 SFE16-43 OLED bản 16GB / 1TB màu Olivine Black, dùng từ sáng đến chiều rất ổn định và mát mẻ. Độ hoàn thiện cao cấp chuẩn doanh nhân, cầm lên tay cảm giác sang trọng và cực kỳ bền bỉ. Đáng đồng tiền bát gạo, rất hài lòng.', '2026-06-20 11:48:00', NULL, 5, 'APPROVED', 315, 63, 37, '2026-06-20 11:48:00');
INSERT INTO reviews (id, comment, created_at, images, rating, status, order_item_id, product_id, user_id, updated_at) VALUES (317, 'Shop tư vấn rất nhiệt tình cấu hình Lenovo Yoga Slim 7 14IMH9 OLED, nhận hàng kiểm tra nguyên seal chính hãng. Độ hoàn thiện cao cấp chuẩn doanh nhân, cầm lên tay cảm giác sang trọng và cực kỳ bền bỉ. Đáng đồng tiền bát gạo, rất hài lòng.', '2026-06-20 21:29:00', NULL, 5, 'APPROVED', 316, 47, 38, '2026-06-20 21:29:00');
INSERT INTO reviews (id, comment, created_at, images, rating, status, order_item_id, product_id, user_id, updated_at) VALUES (318, 'Cấu hình Intel Core i7-13650HX mượt nhưng khi chạy nặng quạt tản nhiệt quay hơi ồn một chút. Tuy vậy nhìn chung tần số quét màn hình cao giúp di chuột và combat game FPS cực đã mắt.', '2026-07-21 08:29:00', NULL, 3, 'APPROVED', 317, 107, 39, '2026-07-21 08:29:00');
INSERT INTO reviews (id, comment, created_at, images, rating, status, order_item_id, product_id, user_id, updated_at) VALUES (319, 'Màn hình Gigabyte U4 UD-50S1823SO Ultrabook đủ nhìn trong nhà, ra ngoài trời nắng gắt độ sáng hơi vừa phải thôi. Tuy vậy nhìn chung bản lề chắc chắn, gõ văn bản nhiều giờ liên tục rất êm tay không ồn.', '2026-07-20 00:29:00', NULL, 3, 'APPROVED', 318, 117, 39, '2026-07-20 00:29:00');
INSERT INTO reviews (id, comment, created_at, images, rating, status, order_item_id, product_id, user_id, updated_at) VALUES (320, 'Bàn phím Acer Nitro V 15 ProPanel ANV15-52-50VA gõ rất nảy, hành trình phím sâu và touchpad di mượt mà chính xác. Card đồ họa NVIDIA GeForce RTX 3050 6GB GDDR6 phát huy sức mạnh rất tốt, nhiệt độ CPU/GPU giữ ở mức an toàn khi chơi lâu. Trải nghiệm mua sắm tuyệt vời, ủng hộ shop lâu dài.', '2026-07-06 07:36:00', NULL, 5, 'APPROVED', 319, 13, 40, '2026-07-06 07:36:00');
INSERT INTO reviews (id, comment, created_at, images, rating, status, order_item_id, product_id, user_id, updated_at) VALUES (321, 'Đặt Lenovo Legion Slim 5 16AHP9 bản 32GB / 1TB dùng tạm ổn, giá vừa túi tiền nhưng loa ngoài âm lượng ở mức trung bình. Tuy vậy nhìn chung độ chuẩn màu màn hình cao giúp làm đồ họa và chỉnh sửa ảnh yên tâm về sai lệch màu.', '2026-06-12 01:23:00', NULL, 3, 'APPROVED', 320, 40, 41, '2026-06-12 01:23:00');
INSERT INTO reviews (id, comment, created_at, images, rating, status, order_item_id, product_id, user_id, updated_at) VALUES (322, 'Pin trên Apple MacBook Air 13 M2 trụ khá tốt cho cả buổi làm việc di động ngoài quán cà phê mà không cần mang sạc. Thiết kế thanh lịch rất hợp môi trường công sở, pin đủ dùng trọn một buổi họp dài. Trải nghiệm mua sắm tuyệt vời, ủng hộ shop lâu dài.', '2026-06-14 08:23:00', NULL, 5, 'APPROVED', 321, 7, 41, '2026-06-14 08:23:00');
INSERT INTO reviews (id, comment, created_at, images, rating, status, order_item_id, product_id, user_id, updated_at) VALUES (323, 'Mức giá hợp lý cho cấu hình Intel Iris Xe Graphics, pin dùng thực tế khoảng 5-7 tiếng tùy tác vụ. Bản lề chắc chắn, gõ văn bản nhiều giờ liên tục rất êm tay không ồn. Hài lòng, phù hợp đúng nhu cầu đặt ra ban đầu.', '2026-06-20 19:36:00', NULL, 4, 'APPROVED', 322, 64, 42, '2026-06-20 19:36:00');
